import { NextRequest } from 'next/server';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest) {
  const encoder = new TextEncoder();
  let intervalId: NodeJS.Timeout;

  const stream = new ReadableStream({
    start(controller) {
      // Send initial connection confirmation
      controller.enqueue(encoder.encode(`event: connected\ndata: {"status":"ready"}\n\n`));

      // Mock live order metric dispatch every 3 seconds
      intervalId = setInterval(() => {
        const payload = JSON.stringify({
          timestamp: Date.now(),
          activeOrders: Math.floor(Math.random() * 20) + 1,
          avgCookTimeMinutes: 14,
        });

        controller.enqueue(encoder.encode(`event: metrics\ndata: ${payload}\n\n`));
      }, 3000);
    },
    cancel() {
      clearInterval(intervalId);
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      'Connection': 'keep-alive',
    },
  });
}

'use client';

import { useEffect, useState } from 'react';

interface MetricData {
  timestamp: number;
  activeOrders: number;
  avgCookTimeMinutes: number;
}

export function LiveKdsMetrics() {
  const [metrics, setMetrics] = useState<MetricData | null>(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const eventSource = new EventSource('/api/kds-stream');

    eventSource.addEventListener('connected', () => {
      setConnected(true);
    });

    eventSource.addEventListener('metrics', (event) => {
      const parsed: MetricData = JSON.parse(event.data);
      setMetrics(parsed);
    });

    eventSource.onerror = () => {
      // Browser will automatically retry connecting
      setConnected(false);
    };

    return () => {
      eventSource.close();
    };
  }, []);

  return (
    <div className="p-4 border rounded-md">
      <div className="flex items-center gap-2">
        <span className={`h-2.5 w-2.5 rounded-full ${connected ? 'bg-emerald-500' : 'bg-red-500'}`} />
        <p className="text-sm font-medium">{connected ? 'Live Stream Active' : 'Reconnecting...'}</p>
      </div>
      {metrics && (
        <div className="mt-4 grid grid-cols-2 gap-4 text-center">
          <div className="bg-slate-50 p-3 rounded">
            <span className="text-2xl font-bold">{metrics.activeOrders}</span>
            <p className="text-xs text-slate-500">Active Kitchen Orders</p>
          </div>
          <div className="bg-slate-50 p-3 rounded">
            <span className="text-2xl font-bold">{metrics.avgCookTimeMinutes}m</span>
            <p className="text-xs text-slate-500">Avg Cook Time</p>
          </div>
        </div>
      )}
    </div>
  );
}
